def StrongestExtension(class_name, extensions):
   strength = 0
   strongest_extension = None
   for extension in extensions:
       uppercase_letters = len([c for c in extension if c.isupper()])
       lowercase_letters = len([c for c in extension if c.islower()])
       strength += abs(uppercase_letters - lowercase_letters)
       if strongest_extension is None or strength > strongest_extension:
           strongest_extension = extension
   return f"{class_name}.{strongest_extension}"

